#!/bin/sh
# Turn a freshly written copy of the master into a new board (offline, on the mounted root filesystem).
# Called by flash.sh:   sh generalize-root.sh /mnt/target
#
# Removes everything that identifies the master board or its site; the clone's first boot
# (host/firstboot.sh via h2z-firstboot*.service) then creates new ones:
#   machine-id, SSH host keys          → regenerated (identity phase)
#   hotspot SSID (from the master MAC) → re-derived from this board's WiFi MAC
#   LAN address                        → back to DHCP
#   .env passwords, secrets/, runtime/ → regenerated by scripts/init.sh (product defaults stay h2z2026 …)
#   Docker volumes (projects, plan docs, Postgres, Tailscale login, DSH model keys, recordings)
#                                      → emptied here, removed and recreated by `docker compose down -v`
#   logs, shell history, temp files    → cleared
# Kept: OS, packages, the repository checkout, pulled images, shared read-only Git deploy key and
# registry login (owner decision 2026-10-16: one shared read-only set for all boards).
set -eu
R=${1:?usage: generalize-root.sh <mounted root>}
R=$(cd "$R" && pwd)
[ "$R" != / ] || { echo "refusing to generalize the running system" >&2; exit 1; }
[ -f "$R/etc/os-release" ] || { echo "$R is not a root filesystem" >&2; exit 1; }
say() { echo "generalize: $*"; }

# ---- repository (found through the linked host units) -------------------------------------------
link=$(readlink "$R/etc/systemd/system/h2z-maint-ap.service" 2>/dev/null || true)
case $link in
  /*/host/systemd/h2z-maint-ap.service) repo=${link%/host/systemd/h2z-maint-ap.service} ;;
  *) echo "h2z host units are not installed on this system (run host/setup-host-network.sh on the master)" >&2; exit 1 ;;
esac
REPO="$R$repo"
[ -f "$REPO/compose.yaml" ] || { echo "repository not found at $repo" >&2; exit 1; }
say "repository $repo"

if [ -f "$REPO/.env" ]; then
  # per-board values: generated again by scripts/init.sh on first boot (only empty values are filled)
  sed -i -E 's/^(POSTGRES_PASSWORD|MQTT_PASSWORD|EMQX_PASSWORD|EMQX_COOKIE|ZLM_SECRET|ZLM_HOOK_SECRET|TS_AUTHKEY|DSH_TRUSTED_NAMES)=.*/\1=/' "$REPO/.env"
fi
rm -rf "$REPO/secrets" "$REPO/runtime/emqx-users.csv" "$REPO/runtime/zlm.ini"
[ -d "$REPO/runtime/ai-shared" ] && find "$REPO/runtime/ai-shared" -mindepth 1 -delete
say "per-board secrets removed"

# ---- Docker: empty the stack's volumes (the containers are stopped: prepare.sh) -----------------
project=$(sed -n 's/^name:[[:space:]]*//p' "$REPO/compose.yaml" | head -1 | tr -d "'\"\r")
[ -n "$project" ] || project=$(basename "$repo" | tr 'A-Z.' 'a-z-')
for v in "$R/var/lib/docker/volumes/${project}_"*; do
  [ -d "$v/_data" ] || continue
  case $(basename "$v") in *_tailscale-cli) continue ;; esac   # just a copy of the tailscale binary
  find "$v/_data" -mindepth 1 -delete
done
say "docker volumes of $project emptied"

# ---- identity ---------------------------------------------------------------------------------
: > "$R/etc/machine-id"
rm -f "$R/var/lib/dbus/machine-id"
rm -f "$R"/etc/ssh/ssh_host_*
say "machine-id and SSH host keys removed"

# ---- host network: hotspot SSID from this board's MAC, LAN back to DHCP ------------------------
H="$R/etc/h2z"
mkdir -p "$H"
if [ -f "$H/host.env" ]; then
  sed -i '/^AP_SSID=/d' "$H/host.env"
  lan_if=$(sed -n "s/^LAN_IF='\(.*\)'$/\1/p" "$H/host.env")
fi
rm -f "$H/lan-previous.yaml" "$H/lan-pending.json" "$H/lan-last-rollback.json" "$H/setup.sha"
if [ -n "${lan_if:-}" ]; then
  cat > "$R/etc/netplan/20-h2z-lan.yaml" <<YAML
# Managed by H2Z host-agent (IOC admin → 设备网络). Original files: /etc/h2z/netplan-orig/
network:
  version: 2
  renderer: networkd
  ethernets:
    $lan_if:
      dhcp4: true
      dhcp6: true
YAML
  chmod 600 "$R/etc/netplan/20-h2z-lan.yaml"
fi
say "LAN ${lan_if:-?} set to DHCP"

# ---- logs, history, temp ----------------------------------------------------------------------
find "$R/var/log" -type f \( -name '*.gz' -o -name '*.[0-9]' -o -name '*.old' \) -delete 2>/dev/null || true
find "$R/var/log" -type f -exec truncate -s 0 {} + 2>/dev/null || true
rm -rf "$R"/var/log/journal/*/ 2>/dev/null || true
for home in "$R/root" "$R"/home/*; do
  [ -d "$home" ] || continue
  rm -f "$home/.bash_history" "$home/.lesshst" "$home/.viminfo" "$home/.python_history" "$home/.node_repl_history" "$home/.wget-hsts"
done
find "$R/tmp" "$R/var/tmp" -mindepth 1 -delete 2>/dev/null || true

# ---- first boot ---------------------------------------------------------------------------------
rm -f "$H/resume-pending" "$H/image-prepared"
date -Is > "$H/firstboot-pending"
date -Is > "$H/firstboot-stack-pending"
for u in h2z-firstboot.service h2z-firstboot-stack.service; do
  [ -L "$R/etc/systemd/system/multi-user.target.wants/$u" ] || { echo "$u is not enabled on the master (run host/image/prepare.sh)" >&2; exit 1; }
done
say "first boot scheduled"
